  1	//! This structure contains a set of SharedGrid structures keyed by
  2	//! unique font configuration.
  3	//!
  4	//! Most terminals (surfaces) will share the same font configuration.
  5	//! This structure allows expensive font information such as
  6	//! the font atlas, glyph cache, font faces, etc. to be shared.
  7	//!
  8	//! This structure is thread-safe when the operations are documented
  9	//! as thread-safe.
 10	const SharedGridSet = @This();
 35	/// The allocator to use for all heap allocations.
 36	alloc: Allocator,
 37	
 38	/// The map of font configurations to SharedGrid instances.
 39	map: Map = .{},
 40	
 41	/// The font library that is used for all font groups.
 42	font_lib: Library,
 43	
 44	/// Font discovery mechanism.
 45	font_discover: ?Discover = null,
 46	
 47	/// Lock to protect multi-threaded access to the map.
 48	lock: std.Io.Mutex = .init,
 49	
 50	pub const InitError = Library.InitError;
 51	
 52	/// Initialize a new SharedGridSet.
 53	pub fn init(alloc: Allocator) InitError!SharedGridSet {
 54	    var font_lib = try Library.init(alloc);
 55	    errdefer font_lib.deinit();
 56	
 57	    return .{
 58	        .alloc = alloc,
 59	        .map = .{},
 60	        .font_lib = font_lib,
 61	    };
 62	}
