 64	pub fn deinit(self: *SharedGridSet) void {
 65	    var it = self.map.iterator();
 66	    while (it.next()) |entry| {
 67	        entry.key_ptr.deinit();
 68	        const v = entry.value_ptr.*;
 69	        v.grid.deinit(self.alloc);
 70	        self.alloc.destroy(v.grid);
 71	    }
 72	    self.map.deinit(self.alloc);
 73	
 74	    if (comptime Discover != void) {
 75	        if (self.font_discover) |*v| v.deinit();
 76	    }
 77	
 78	    self.font_lib.deinit();
 79	}
