 81	/// Returns the number of cached grids.
 82	pub fn count(self: *SharedGridSet) usize {
 83	    self.lock.lockUncancelable(global.io());
 84	    defer self.lock.unlock(global.io());
 85	    return self.map.count();
 86	}
